func (t *Tracker) Export(outputPath string, format string) error {
        exps := t.store.ListExperiments("")

        switch format {
        case "json":
                data, err := json.MarshalIndent(exps, "", "  ")
                if err != nil {
                        return err
                }
                return os.WriteFile(outputPath, data, 0644)
        case "csv":
                f, err := os.Create(outputPath)
                if err != nil {
                        return err
                }
                defer f.Close()

                fmt.Fprintln(f, "id,name,status,start_time")
                for _, exp := range exps {
                        fmt.Fprintf(f, "%s,%s,%s,%s\n", exp.ID, exp.Name, exp.Status, exp.StartTime.Format(time.RFC3339))
                }
                return nil
        default:
                return fmt.Errorf("unsupported export format: %s", format)
        }
}
